mapper.select:
select * from qa_session where tenant_id=#{tenantId} and course_id=#{courseId}
  and user_id=#{userId} and del_flag='0' and status='active'
order by coalesce(update_time, create_time) desc, id desc

mapper.update:
update qa_session set del_flag='2',status='deleted',update_by=#{userId},update_time=now()
where tenant_id=#{tenantId} and course_id=#{courseId} and user_id=#{userId}
  and id=#{sessionId} and del_flag='0'

update qa_message_citation c set del_flag='2',update_time=now()
where c.tenant_id=#{tenantId} and c.del_flag='0'
  and exists (
    select 1 from qa_message m
    where m.tenant_id=c.tenant_id and m.id=c.message_id and m.session_id=#{sessionId}
  )
